    r"""^AI: finance: est income (-?\d+), est maintenance (-?\d+), est outgoings (-?\d+) -- spending max (-?\d+), spending norm (-?\d+); balance (\w+), state (AFS_\w+)""",
    r"""^AI: -- building '([^']+)' at priority (\d+)""",
